CREATE TABLE users (id BIGINT AUTO_INCREMENT PRIMARY KEY,names VARCHAR(100) NOT NULL,surnames VARCHAR(100) NOT NULL,document_type VARCHAR(30) NOT NULL,document_number VARCHAR(50) NOT NULL,email VARCHAR(254) NOT NULL,phone VARCHAR(30) NOT NULL,password_hash VARCHAR(255) NOT NULL,role VARCHAR(30) NOT NULL,active BOOLEAN NOT NULL,created_at TIMESTAMP(6) NOT NULL,CONSTRAINT uk_users_email UNIQUE(email),CONSTRAINT uk_users_document UNIQUE(document_type,document_number));
CREATE TABLE refresh_sessions (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,token_hash CHAR(64) NOT NULL,expires_at TIMESTAMP(6) NOT NULL,revoked BOOLEAN NOT NULL,CONSTRAINT uk_refresh_hash UNIQUE(token_hash),CONSTRAINT fk_refresh_user FOREIGN KEY(user_id) REFERENCES users(id));
